-- Games (ROMs ship in the client's Patch-ZzzzzzzzzzzEsteriaArcadeRoms.MPQ; cores in <client>\Arcade\Cores) and which
-- gameobject entry plays which game at what price (copper; 0 = free). Rows are generated by
-- wowdecomp Tools/Arcade/pack.py (arcade_content.sql).
CREATE TABLE IF NOT EXISTS `esteria_arcade_game` (
  `id` INT UNSIGNED NOT NULL,
  `title` VARCHAR(100) NOT NULL,
  `system` VARCHAR(16) NOT NULL,
  `core` VARCHAR(48) NOT NULL,
  `rom` TEXT NOT NULL, -- archive paths joined by | (game first, then the files that sit beside it)
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `esteria_arcade_cabinet` (
  `entry` INT UNSIGNED NOT NULL,
  `game` INT UNSIGNED NOT NULL,
  `price` INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Cabinet looks a house owner can switch a placed cabinet to (skin 0, the Lionheart model, is every cabinet's own).
CREATE TABLE IF NOT EXISTS `esteria_arcade_skin` (
  `id` INT UNSIGNED NOT NULL,
  `display_id` INT UNSIGNED NOT NULL,
  `price` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'copper to unlock, once per account',
  `name` VARCHAR(64) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
